Here's an example C++ program that reads a text file line by line and counts the number of occurrences of a specific word:

```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <map>

int main() {
    std::string filename, search_word;
    std::cout << "Enter filename: ";
    std::cin >> filename;

    std::cout << "Enter word to search: ";
    std::cin >> search_word;

    std::ifstream file(filename);
    if (!file.is_open()) {
        std::cerr << "Error opening file: " << filename << std::endl;
        return 1;
    }

    std::map<std::string, int> word_count;
    int line_number = 0;

    std::string line;
    while (std::getline(file, line)) {
        line_number++;

        std::size_t pos = 0;
        while ((pos = line.find(search_word, pos)) != std::string::npos) {
            word_count[search_word]++;
            pos += search_word.length();
        }
    }

    file.close();

    std::cout << "Word '" << search_word << "' appears " << word_count[search_word] << " times in " << filename << ":\n";

    for (const auto& entry : word_count) {
        std::cout << "Line " << entry.first << " (line " << entry.second << "): " << entry.first << std::endl;
    }

    return 0;
}
```

